const setupForm=document.querySelector('#admin-setup'),setupStatus=document.querySelector('#setup-status'),setupButton=setupForm.querySelector('button');
fetch('/api/setup/status').then(async response=>{const body=await response.json();if(!response.ok)throw new Error(body.error);if(!body.enabled){setupForm.hidden=true;setupStatus.textContent=body.configured?'Admin setup is closed. Sign in below or contact your website administrator.':'Admin setup is ready for review. Connect the backend and set its private setup code to enable account creation.';return;}setupStatus.textContent='Ready to create your first admin account.';setupButton.disabled=false;}).catch(()=>{setupStatus.textContent='Admin setup is not connected yet. You can preview the dashboard using the link above.';});
setupForm.onsubmit=async event=>{event.preventDefault();const form=new FormData(setupForm);if(form.get('password')!==document.querySelector('#confirm-password').value){setupStatus.textContent='Passwords do not match.';return;}setupButton.disabled=true;setupStatus.textContent='Creating your account…';try{const response=await fetch('/api/setup/admin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(form))});const body=await response.json();if(!response.ok)throw new Error(body.error);setupForm.reset();setupForm.hidden=true;setupStatus.textContent='Admin account created. You can now sign in to the studio dashboard.';}catch(error){setupStatus.textContent=error.message;setupButton.disabled=false;}};
